template:
router bgp {{1}}
  no bgp default ipv4-unicast
  network 192.168.1.0 mask 255.255.255.0
  neighbor 172.16.10.2 remote-as {{2}}
  neighbor 172.16.20.2 remote-as {{3}}
  address-family ipv4 unicast
    neighbor {{4}} activate
    exit-address-family
  address-family ipv4 {{5}}
    neighbor 172.16.20.2 activate
    exit-address-family
